@import "tailwindcss";

:root {
  --background: #edf4ff;
  --foreground: #0f172a;
}

@theme inline {
  --color-background: var(--background);
  --color-surface: #ffffff;
  --color-surface-muted: #f9fafb;
  --color-title: #111827;
  --color-muted: #4b5563;
  --color-primary: #1e3a8a;
  --color-primary-hover: #2563eb;
  --color-accent: #4338ca;
  --color-accent-hover: #6366f1;
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

html {
  background: var(--background);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-geist-sans), sans-serif;
}

* {
  scrollbar-width: thin;
  scrollbar-color: #bfdbfe transparent;
}

::selection {
  background: #bae6fd;
  color: #0f172a;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import { Providers } from "@/components/providers";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "Inbox de Atendimento | Myde",
  description: "Painel de atendimento WhatsApp com IA, sincronizado com API online.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="pt-BR"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full flex flex-col bg-background font-sans text-title">
        <Providers>{children}</Providers>
      </body>
    </html>
  );
}

"use client";

import { useDeferredValue, useMemo, useState } from "react";
import { ChatPanel } from "@/components/inbox/chat-panel";
import { ConversationList } from "@/components/inbox/conversation-list";
import { useConversations } from "@/hooks/use-conversations";
import { useMessages } from "@/hooks/use-messages";
import { useProfile } from "@/hooks/use-profile";
import { cn } from "@/lib/utils";

export function InboxApp() {
  const [selectedConversationId, setSelectedConversationId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const deferredSearchTerm = useDeferredValue(searchTerm);

  const profileQuery = useProfile();
  const conversationsQuery = useConversations();
  const selectedConversation =
    conversationsQuery.data?.find(
      (conversation) => conversation.id === selectedConversationId,
    ) ?? null;
  const messagesQuery = useMessages(selectedConversationId);

  const filteredConversations = useMemo(() => {
    const conversations = conversationsQuery.data ?? [];
    const normalizedTerm = deferredSearchTerm.trim().toLowerCase();

    if (!normalizedTerm) {
      return conversations;
    }

    return conversations.filter((conversation) =>
      [conversation.contactName, conversation.contactPhone, conversation.lastMessage]
        .join(" ")
        .toLowerCase()
        .includes(normalizedTerm),
    );
  }, [conversationsQuery.data, deferredSearchTerm]);

  return (
    <main className="min-h-screen bg-background px-4 py-4 text-title sm:px-6 lg:px-8 lg:py-8">
      <div className="mx-auto flex min-h-[calc(100vh-2rem)] max-w-7xl flex-col gap-4 lg:min-h-[calc(100vh-4rem)] lg:flex-row">
        <div className={cn("min-h-0 lg:flex", selectedConversationId ? "hidden lg:flex" : "flex")}>
          <ConversationList
            conversations={filteredConversations}
            activeConversationId={selectedConversationId}
            isLoading={conversationsQuery.isLoading}
            isError={conversationsQuery.isError}
            searchTerm={searchTerm}
            onSearchTermChange={setSearchTerm}
            onSelectConversation={setSelectedConversationId}
            onRetry={() => conversationsQuery.refetch()}
          />
        </div>

        <div className={cn("min-h-0 flex-1", selectedConversationId ? "flex" : "hidden lg:flex")}>
          <div className="flex min-h-0 flex-1 flex-col gap-4">
            <section className="rounded-[1.25rem] border border-gray-200 bg-surface px-5 py-4 shadow-sm">
              <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
                <div>
                  <p className="text-xs font-semibold uppercase tracking-[0.28em] text-primary">
                    Painel ativo
                  </p>
                  <h1 className="mt-2 text-2xl font-semibold tracking-tight text-title">
                    {profileQuery.data?.name ?? "Carregando atendente..."}
                  </h1>
                  <p className="mt-1 text-sm text-muted">
                    {profileQuery.data?.role ?? "Sincronizando perfil com a API online."}
                  </p>
                </div>

                <div className="flex flex-wrap gap-3 text-sm text-muted">
                  <div className="rounded-xl bg-surface-muted px-3 py-2">
                    {conversationsQuery.data?.length ?? 0} conversas monitoradas
                  </div>
                  <div className="rounded-xl bg-surface-muted px-3 py-2 text-accent">
                    {selectedConversation ? "Chat em foco" : "Nenhum chat selecionado"}
                  </div>
                  <div
                    className={cn(
                      "rounded-xl px-3 py-2",
                      profileQuery.isError
                        ? "bg-red-50 text-red-700"
                        : "bg-surface-muted text-primary",
                    )}
                  >
                    {profileQuery.isError ? "API instavel" : "API conectada"}
                  </div>
                </div>
              </div>
            </section>

            <ChatPanel
              conversation={selectedConversation}
              messages={messagesQuery.data ?? []}
              isLoading={messagesQuery.isLoading}
              isError={messagesQuery.isError}
              onBack={() => setSelectedConversationId(null)}
              onRetry={() => messagesQuery.refetch()}
            />
          </div>
        </div>
      </div>
    </main>
  );
}

import { useEffect, useRef } from "react";
import { EmptyState } from "@/components/inbox/inbox-states";
import { MessageComposer } from "@/components/inbox/message-composer";
import { type Conversation, type Message } from "@/lib/types";
import { cn, formatMessageStatus, formatMessageTime, formatPhoneNumber, getInitials } from "@/lib/utils";

type ChatPanelProps = {
  conversation: Conversation | null;
  messages: Message[];
  isLoading: boolean;
  isError: boolean;
  onBack: () => void;
  onRetry: () => void;
};

export function ChatPanel({ conversation, messages, isLoading, isError, onBack, onRetry }: ChatPanelProps) {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const element = scrollRef.current;
    if (!element) {
      return;
    }

    element.scrollTop = element.scrollHeight;
  }, [conversation?.id, messages.length]);

  if (!conversation) {
    return (
      <div className="hidden min-h-0 flex-1 lg:flex">
        <EmptyState
          title="Escolha uma conversa"
          description="Selecione um contato para visualizar o historico, responder com update otimista e usar a sugestao de IA."
        />
      </div>
    );
  }

  return (
    <section className="flex min-h-0 flex-1 flex-col rounded-[1.25rem] border border-gray-200 bg-surface shadow-sm">
      <header className="flex items-center gap-4 border-b border-gray-200 px-5 py-4">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex h-10 w-10 items-center justify-center rounded-xl border border-gray-300 bg-surface text-muted transition hover:border-gray-400 hover:text-title lg:hidden"
          aria-label="Voltar para a lista de conversas"
        >
          ←
        </button>
        <div
          className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl text-sm font-semibold text-white"
          style={{ backgroundColor: conversation.avatarColor }}
        >
          {getInitials(conversation.contactName)}
        </div>
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-lg font-semibold text-title">{conversation.contactName}</h2>
          <p className="truncate text-sm text-muted">{formatPhoneNumber(conversation.contactPhone)}</p>
        </div>
        <div className="hidden rounded-xl bg-surface-muted px-3 py-1 text-xs font-medium text-primary sm:block">
          Sincronizacao ativa
        </div>
      </header>

      <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto px-4 py-5 sm:px-6">
        {isLoading ? (
          <div className="space-y-3">
            {Array.from({ length: 5 }).map((_, index) => (
                <div key={index} className={cn("flex", index % 2 === 0 ? "justify-start" : "justify-end")}>
                <div className="h-20 w-full max-w-md animate-pulse rounded-2xl bg-surface-muted" />
              </div>
            ))}
          </div>
        ) : null}

        {!isLoading && isError ? (
          <EmptyState
            title="Erro ao carregar o chat"
            description="A conversa nao pode ser sincronizada agora. Tente novamente em instantes."
          />
        ) : null}

        {!isLoading && !isError && messages.length === 0 ? (
          <EmptyState
            title="Nenhuma mensagem ainda"
            description="Inicie o atendimento manualmente ou gere uma sugestao de resposta com IA."
          />
        ) : null}

        {!isLoading && !isError && messages.length > 0 ? (
          <ol className="space-y-3">
            {messages.map((message) => {
              const isAgent = message.direction === "out";

              return (
                <li key={message.id} className={cn("flex", isAgent ? "justify-end" : "justify-start")}>
                  <article
                    className={cn(
                      "max-w-[85%] rounded-2xl px-4 py-3 shadow-sm sm:max-w-[70%]",
                      isAgent ? "bg-primary text-white" : "bg-surface text-title",
                    )}
                  >
                    <p className="text-sm leading-6">{message.body}</p>
                    <div
                      className={cn(
                        "mt-2 flex items-center justify-end gap-2 text-[11px] font-medium",
                        isAgent ? "text-slate-200" : "text-muted",
                      )}
                    >
                      <span>{formatMessageStatus(message.status)}</span>
                      <time dateTime={message.createdAt}>{formatMessageTime(message.createdAt)}</time>
                    </div>
                  </article>
                </li>
              );
            })}
          </ol>
        ) : null}
      </div>

      {isError ? (
        <div className="border-t border-gray-200 px-5 py-4">
          <button
            type="button"
            onClick={onRetry}
            className="rounded-xl bg-primary px-4 py-2 text-sm font-medium text-white transition hover:bg-primary-hover"
          >
            Recarregar conversa
          </button>
        </div>
      ) : (
        <MessageComposer conversationId={conversation.id} disabled={false} />
      )}
    </section>
  );
}

import { SidebarState } from "@/components/inbox/inbox-states";
import { type Conversation } from "@/lib/types";
import { cn, formatConversationTime, formatPhoneNumber, getInitials } from "@/lib/utils";

type ConversationListProps = {
  conversations: Conversation[];
  activeConversationId: string | null;
  isLoading: boolean;
  isError: boolean;
  searchTerm: string;
  onSearchTermChange: (value: string) => void;
  onSelectConversation: (conversationId: string) => void;
  onRetry: () => void;
};

export function ConversationList({
  conversations,
  activeConversationId,
  isLoading,
  isError,
  searchTerm,
  onSearchTermChange,
  onSelectConversation,
  onRetry,
}: ConversationListProps) {
  return (
    <aside className="flex h-full min-h-0 w-full flex-col rounded-[1.25rem] border border-gray-200 bg-surface p-4 shadow-sm lg:max-w-95">
      <div className="px-2 pb-4 pt-2">
        <p className="text-xs font-semibold uppercase tracking-[0.28em] text-primary">
          Conversas
        </p>
        <div className="mt-3 flex items-end justify-between gap-3">
          <div>
            <h1 className="text-2xl font-semibold tracking-tight text-title">
              Atendimento WhatsApp
            </h1>
            <p className="mt-1 text-sm text-muted">
              Busca local com sincronizacao periodica da API.
            </p>
          </div>
          <div className="rounded-xl bg-surface-muted px-3 py-1 text-xs font-medium text-primary">
            Online
          </div>
        </div>
        <label className="mt-5 block">
          <span className="sr-only">Buscar conversas</span>
          <input
            value={searchTerm}
            onChange={(event) => onSearchTermChange(event.target.value)}
            placeholder="Buscar por nome, telefone ou mensagem"
              className="w-full rounded-xl border border-gray-200 bg-surface-muted px-4 py-3 text-sm text-title outline-none transition focus:border-primary-hover focus:bg-surface focus:ring-4 focus:ring-blue-100"
          />
        </label>
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto px-2 pb-2">
        {isLoading ? (
          <div className="space-y-3 py-2">
            {Array.from({ length: 6 }).map((_, index) => (
              <div key={index} className="animate-pulse rounded-2xl border border-gray-200 bg-surface-muted p-4">
                <div className="flex items-center gap-3">
                  <div className="h-12 w-12 rounded-xl bg-gray-200" />
                  <div className="flex-1 space-y-2">
                    <div className="h-4 w-2/3 rounded-full bg-gray-200" />
                    <div className="h-3 w-full rounded-full bg-gray-200" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : null}

        {!isLoading && isError ? (
          <SidebarState
            title="Nao foi possivel carregar as conversas"
            description="Verifique a conexao com a API e tente novamente."
            action={
              <button
                type="button"
                onClick={onRetry}
                className="rounded-xl bg-primary px-4 py-2 text-sm font-medium text-white transition hover:bg-primary-hover"
              >
                Tentar novamente
              </button>
            }
          />
        ) : null}

        {!isLoading && !isError && conversations.length === 0 ? (
          <SidebarState
            title="Nada encontrado"
            description="Ajuste os filtros ou aguarde novas interacoes chegarem pela API."
          />
        ) : null}

        {!isLoading && !isError && conversations.length > 0 ? (
          <ul className="space-y-3">
            {conversations.map((conversation) => {
              const isActive = conversation.id === activeConversationId;

              return (
                <li key={conversation.id}>
                  <button
                    type="button"
                    onClick={() => onSelectConversation(conversation.id)}
                    className={cn(
                      "w-full rounded-2xl border p-4 text-left transition focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-blue-100",
                      isActive
                        ? "border-blue-200 bg-surface-muted shadow-sm"
                        : "border-gray-200 bg-surface hover:border-gray-300 hover:bg-surface-muted",
                    )}
                    aria-pressed={isActive}
                  >
                    <div className="flex items-start gap-3">
                      <div
                        className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl text-sm font-semibold text-white"
                        style={{ backgroundColor: conversation.avatarColor }}
                      >
                        {getInitials(conversation.contactName)}
                      </div>

                      <div className="min-w-0 flex-1">
                        <div className="flex items-start justify-between gap-3">
                          <div className="min-w-0">
                            <p className="truncate text-sm font-semibold text-title">
                              {conversation.contactName}
                            </p>
                            <p className="mt-1 truncate text-xs text-muted">
                              {formatPhoneNumber(conversation.contactPhone)}
                            </p>
                          </div>
                          <div className="flex shrink-0 flex-col items-end gap-2">
                            <time
                              dateTime={conversation.lastMessageAt}
                              className="text-xs font-medium text-muted"
                            >
                              {formatConversationTime(conversation.lastMessageAt)}
                            </time>
                            <span
                              className={cn(
                                "inline-flex items-center gap-2 rounded-lg px-2.5 py-1 text-[11px] font-semibold",
                                conversation.unread > 0
                                  ? "bg-blue-50 text-primary"
                                  : "bg-surface-muted text-muted",
                              )}
                            >
                              <span
                                className={cn(
                                  "h-2 w-2 rounded-sm",
                                  conversation.unread > 0 ? "bg-primary" : "bg-gray-300",
                                )}
                              />
                              {conversation.unread > 0
                                ? `${conversation.unread} nao lida${conversation.unread > 1 ? "s" : ""}`
                                : "Lida"}
                            </span>
                          </div>
                        </div>

                        <div className="mt-3 flex items-center justify-between gap-3">
                          <p className="line-clamp-2 text-sm leading-6 text-muted">
                            {conversation.lastMessage}
                          </p>
                        </div>
                      </div>
                    </div>
                  </button>
                </li>
              );
            })}
          </ul>
        ) : null}
      </div>
    </aside>
  );
}

"use client";

import { startTransition, useState } from "react";
import { useAiSuggest } from "@/hooks/use-ai-suggest";
import { useSendMessage } from "@/hooks/use-send-message";

type MessageComposerProps = {
  conversationId: string;
  disabled: boolean;
};

export function MessageComposer({ conversationId, disabled }: MessageComposerProps) {
  const [draft, setDraft] = useState("");
  const [feedback, setFeedback] = useState<string | null>(null);
  const sendMessageMutation = useSendMessage();
  const aiSuggestMutation = useAiSuggest();

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    const text = draft.trim();
    if (!text) {
      return;
    }

    setFeedback(null);

    try {
      await sendMessageMutation.mutateAsync({ conversationId, text });
      setDraft("");
      setFeedback("Mensagem enviada.");
    } catch {
      setFeedback("Nao foi possivel enviar a mensagem.");
    }
  }

  async function handleSuggest() {
    setFeedback(null);

    try {
      const response = await aiSuggestMutation.mutateAsync(conversationId);
      startTransition(() => {
        setDraft(response.suggestion);
      });
      setFeedback("Sugestao preenchida no campo de resposta.");
    } catch {
      setFeedback("Nao foi possivel gerar a sugestao com IA.");
    }
  }

  return (
    <form onSubmit={handleSubmit} className="border-t border-gray-200 px-5 py-4">
      <div className="rounded-2xl border border-gray-200 bg-surface p-3 shadow-sm">
        <label className="sr-only" htmlFor="message-draft">
          Responder conversa
        </label>
        <textarea
          id="message-draft"
          rows={3}
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Escreva uma resposta clara e objetiva..."
          disabled={disabled || sendMessageMutation.isPending}
          className="w-full resize-none border-none bg-transparent px-2 py-2 text-sm leading-6 text-title outline-none placeholder:text-gray-400"
        />

        <div className="flex flex-col gap-3 border-t border-gray-100 pt-3 md:flex-row md:items-center md:justify-between">
          <div className="flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={handleSuggest}
              disabled={disabled || aiSuggestMutation.isPending}
              className="rounded-xl border border-indigo-200 bg-surface-muted px-4 py-2 text-sm font-medium text-accent transition hover:border-indigo-300 hover:bg-indigo-50 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {aiSuggestMutation.isPending ? "Gerando sugestao..." : "Sugerir com IA"}
            </button>
            <span className="text-xs text-muted">
              A IA preenche o texto; o envio continua manual.
            </span>
          </div>

          <button
            type="submit"
            disabled={disabled || sendMessageMutation.isPending || !draft.trim()}
            className="inline-flex items-center justify-center rounded-xl bg-primary px-5 py-2.5 text-sm font-medium text-white transition hover:bg-primary-hover disabled:cursor-not-allowed disabled:opacity-50"
          >
            {sendMessageMutation.isPending ? "Enviando..." : "Enviar mensagem"}
          </button>
        </div>
      </div>

      <p aria-live="polite" className="mt-3 min-h-5 text-sm text-muted">
        {feedback}
      </p>
    </form>
  );
}

type EmptyStateProps = {
  title: string;
  description: string;
};

type SidebarStateProps = EmptyStateProps & {
  action?: React.ReactNode;
};

export function EmptyState({ title, description }: EmptyStateProps) {
  return (
    <div className="flex min-h-0 flex-1 items-center justify-center p-6">
      <div className="max-w-sm rounded-2xl border border-gray-200 bg-surface p-8 text-center shadow-sm">
        <p className="text-sm font-semibold uppercase tracking-[0.24em] text-primary">
          Inbox Myde
        </p>
        <h2 className="mt-4 text-2xl font-semibold text-title">{title}</h2>
        <p className="mt-3 text-sm leading-6 text-muted">{description}</p>
      </div>
    </div>
  );
}

export function SidebarState({ title, description, action }: SidebarStateProps) {
  return (
    <div className="rounded-2xl border border-dashed border-gray-300 bg-surface-muted px-5 py-8 text-center">
      <h3 className="text-base font-semibold text-title">{title}</h3>
      <p className="mt-2 text-sm leading-6 text-muted">{description}</p>
      {action ? <div className="mt-4">{action}</div> : null}
    </div>
  );
}

import { useEffect, useRef } from "react";
import { EmptyState } from "@/components/inbox/inbox-states";
import { MessageComposer } from "@/components/inbox/message-composer";
import { type Conversation, type Message } from "@/lib/types";
import { cn, formatMessageStatus, formatMessageTime, formatPhoneNumber, getInitials } from "@/lib/utils";

type ChatPanelProps = {
  conversation: Conversation | null;
  messages: Message[];
  isLoading: boolean;
  isError: boolean;
  onBack: () => void;
  onRetry: () => void;
};

export function ChatPanel({ conversation, messages, isLoading, isError, onBack, onRetry }: ChatPanelProps) {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const element = scrollRef.current;
    if (!element) {
      return;
    }

    element.scrollTop = element.scrollHeight;
  }, [conversation?.id, messages.length]);

  if (!conversation) {
    return (
      <div className="hidden min-h-0 flex-1 lg:flex">
        <EmptyState
          title="Escolha uma conversa"
          description="Selecione um contato para visualizar o historico, responder com update otimista e usar a sugestao de IA."
        />
      </div>
    );
  }

  return (
    <section className="flex min-h-0 flex-1 flex-col rounded-[1.25rem] border border-gray-200 bg-surface shadow-sm">
      <header className="flex items-center gap-4 border-b border-gray-200 px-5 py-4">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex h-10 w-10 items-center justify-center rounded-xl border border-gray-300 bg-surface text-muted transition hover:border-gray-400 hover:text-title lg:hidden"
          aria-label="Voltar para a lista de conversas"
        >
          ←
        </button>
        <div
          className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl text-sm font-semibold text-white"
          style={{ backgroundColor: conversation.avatarColor }}
        >
          {getInitials(conversation.contactName)}
        </div>
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-lg font-semibold text-title">{conversation.contactName}</h2>
          <p className="truncate text-sm text-muted">{formatPhoneNumber(conversation.contactPhone)}</p>
        </div>
        <div className="hidden rounded-xl bg-surface-muted px-3 py-1 text-xs font-medium text-primary sm:block">
          Sincronizacao ativa
        </div>
      </header>

